class StorageModuleClient:
    """The blocking twin of :class:`AsyncStorageModuleClient`, over a
    :class:`logos_bridge.BridgeClient`.
    """

    def __init__(self, bridge: _BridgeClient, module: str = MODULE_NAME) -> None:
        self._bridge = bridge
        self._portal = bridge.portal
        self._aio = AsyncStorageModuleClient(bridge.aio, module)

    def __repr__(self) -> str:
        return f"<StorageModuleClient {self._aio.module} on {self._bridge.url}>"

    @property
    def aio(self) -> AsyncStorageModuleClient:
        return self._aio

    @property
    def bridge(self) -> _BridgeClient:
        return self._bridge

    @property
    def module(self) -> str:
        return self._aio.module

    @property
    def portal(self) -> _BlockingPortal:
        return self._portal

    def migrate_config(self, cfg: str, *, timeout: float | None = None) -> _t.LogosResult[_typing.Any]:
        """Migrate the configuration after a Storage Module update.

        This method takes a configuration string in parameters and returns
        a new configuration JSON string updated.

        Depending on the updates of logos-storage-nim, some options can be removed
        or replaced with new ones. This method ensures a migration path for the
        configuration to the latest version of the module using a configuration version.

        In addition to the migration, the data-dir is also set if it is not provided
        in configuration. And with `mix-enabled` true plus a network key, the mix
        configuration is updated.

        This method should be called before `init()`. It is a separate step so
        the caller can get the result of the new configuration and update it.

        Returns StdLogosResult::value as the JSON to hand to init().

        LIDL: ``method migrateConfig(cfg: tstr) -> result``

        Args:
            cfg: ``tstr``.
            timeout: seconds to wait for the answer (default: the bridge client's).

        Returns:
            The ``result``. ``success=False`` is an answer, not an exception;
            :meth:`LogosResult.unwrap` turns it into one.

        Raises:
            ArgumentError: an argument does not match the contract (nothing is sent).
            ProviderRejection: the provider refused the call.
            ResultDecodeError: the result does not match the contract.
            MethodNotFound: this bridge does not expose the method.
        """
        return self._portal.call(self._aio.migrate_config, cfg, timeout=timeout)

    def init(self, cfg: str, *, timeout: float | None = None) -> bool:
        """Create a new storage node instance and configure it.

        `cfg` is a JSON string with the configuration overwriting defaults.

        Example of JSON config:

        ::

            {
            "log-level": "info",
            "log-format": "auto",
            "metrics": false,
            "metrics-address": "127.0.0.1",
            "metrics-port": 8008,
            "data-dir": ".cache/storage",
            "listen-ip": "0.0.0.0",
            "listen-port": 0,
            "nat": "auto",
            "net-privkey": "key",
            "bootstrap-node": [],
            "no-bootstrap-node": false,
            "network": "logos.test",
            "dht-mix-proxy": [],
            "mix-enabled": false,
            "mix-pool": "",
            "mix-pool-json": "",
            "max-peers": 160,
            "num-threads": 0,
            "agent-string": "Logos Storage",
            "repo-kind": "fs",
            "storage-quota": 21474836480,
            "block-ttl": "30d",
            "block-mi": "10m",
            "block-mn": 1000,
            "block-retries": 300,
            "log-file": "/tmp/storage-log-624036264.log",
            "nat-schedule-interval": "2m",
            "nat-num-peers-to-ask": 3,
            "nat-max-queue-size": 3,
            "nat-min-confidence": 0.6,
            "nat-observed-addr-min-count": 1,
            "nat-max-relays": 2,
            "nat-port-mapping-discover-timeout": 500,
            "nat-port-mapping-timeout": 500,
            "nat-port-mapping-recheck-period": 300000
            }

        Do not call init() more than once per instance.

        Returns true on success.  The method is synchronous.

        LIDL: ``method init(cfg: tstr) -> bool``

        Args:
            cfg: ``tstr``.
            timeout: seconds to wait for the answer (default: the bridge client's).

        Returns:
            ``bool``.

        Raises:
            ArgumentError: an argument does not match the contract (nothing is sent).
            ProviderRejection: the provider refused the call.
            ResultDecodeError: the result does not match the contract.
            MethodNotFound: this bridge does not expose the method.
        """
        return self._portal.call(self._aio.init, cfg, timeout=timeout)

